def calculate_S(N):
    """Calculates S(N) = sum_{a=1}^N sum_{b=1}^N floor(ab / (N+1))."""
    S_N = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S_N += (a * b) // (N + 1)
    return S_N

def calculate_target(N):
    """Calculates the target value (N^3 - N^2 + 2) / 4."""
    return (N**3 - N**2 + 2) / 4

N_values = [1, 2, 3, 4, 5]
results = {}

for N in N_values:
    S_N = calculate_S(N)
    target_N = calculate_target(N)
    results[N] = {
        "S(N)": S_N,
        "Target": target_N,
        "Match": S_N == target_N
    }

print("--- Results for N=1 to N=5 ---")
for N, res in results.items():
    print(f"N={N}: S(N) = {res['S(N)']}, Target = {res['Target']}. Match: {res['Match']}")

