def calculate_Q(M):
    """Calculates Q_actual(M) = sum_{a=1}^{M-1} sum_{b=1}^{M-1} (ab mod M)"""
    Q_sum = 0
    for a in range(1, M):
        for b in range(1, M):
            Q_sum += (a * b) % M
    return Q_sum

def calculate_Q_req(M):
    """Calculates Q_req(M) = M^2 * (M-2) / 2"""
    return M**2 * (M - 2) // 2

